<div class="modal-backdrop app-modal-host" id="medicineQuickModal" aria-hidden="true"><div class="app-modal-dialog" data-size="lg" role="dialog" aria-modal="true" aria-labelledby="medicineQuickTitle"><form id="medicineQuickForm" class="app-modal-form" novalidate autocomplete="off"><div class="modal-header"><div class="modal-header-copy"><h2 id="medicineQuickTitle">Add Medicine</h2><p>Create a Medicine and price without leaving the Consultation.</p></div><button class="modal-close" id="medicineQuickClose" type="button" aria-label="Close"><i data-lucide="x"></i></button></div><div class="modal-body"><div class="form-row"><div class="field col-4"><label>Medicine Code</label><input id="quickMedicineCode" type="text" readonly></div><div class="field col-8"><label for="quickMedicineName" class="required">Medicine Name</label><input id="quickMedicineName" name="medicine_name" type="text" maxlength="255" required></div></div><div class="form-row"><div class="field col-4"><label for="quickMedicineType" class="required">Medicine Type</label><select id="quickMedicineType" name="medicine_type" required><option value="">Select Type</option><option>Kashayam</option><option>Churna</option><option>Tablet</option><option>Capsule</option><option>Lehya</option><option>Tailam</option><option>Ghrita</option><option>Arishta / Asava</option><option>Syrup</option><option>Powder</option><option>Oil</option><option>Other</option></select></div><div class="field col-2"><label>Unit</label><input name="unit" type="text" maxlength="100" placeholder="Bottle"></div><div class="field col-2"><label>Pack Size</label><input name="pack_size" type="text" maxlength="100" placeholder="200 ml"></div><div class="field col-2"><label for="quickMedicinePrice" class="required">Price</label><input id="quickMedicinePrice" name="selling_price" type="text" inputmode="decimal" value="0.00" required></div><div class="field col-2"><label>Status</label><select id="quickMedicineStatus" name="status"><option value="1">Active</option><option value="0">Inactive</option></select></div></div></div><div class="modal-footer"><div class="buttons"><button class="btn gray" id="medicineQuickCancel" type="button">Cancel</button><button class="btn btn-primary" id="medicineQuickSave" type="submit"><i data-lucide="save"></i> Save Medicine</button></div></div></form></div></div>
<script>(function(window,document){'use strict';var modal=document.getElementById('medicineQuickModal'),form=document.getElementById('medicineQuickForm'),save=document.getElementById('medicineQuickSave'),onSaved=null,typeSelect=GlobalSelect.init('#quickMedicineType',{placeholder:'Select Type'}),statusSelect=GlobalSelect.init('#quickMedicineStatus',{placeholder:'Status'});function openModal(){modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');setTimeout(function(){document.getElementById('quickMedicineName').focus();},50);if(window.lucide)window.lucide.createIcons();}function closeModal(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');onSaved=null;}async function openCreate(options){options=options||{};try{var response=await App.api('api/medicines.php?options=1'),data=response.data||{},actions=(data.allowed_actions||[]).map(Number);if(actions.indexOf(2)===-1){showToast('You do not have permission to create Medicine.',{type:'danger',duration:3});return;}form.reset();document.getElementById('quickMedicineCode').value=data.next_medicine_code||'';document.getElementById('quickMedicinePrice').value='0.00';form.status.value='1';if(typeSelect&&typeof typeSelect.sync==='function')typeSelect.sync();if(statusSelect&&typeof statusSelect.sync==='function')statusSelect.sync();onSaved=typeof options.onSaved==='function'?options.onSaved:null;openModal();}catch(error){App.showError(error,'Unable to prepare Medicine form.');}}form.addEventListener('submit',async function(event){event.preventDefault();Validation.clearForm(form);if(!Validation.validateForm(form))return;save.disabled=true;try{var data=new FormData(form);data.set('action','save');var response=await App.api('api/medicines.php',{method:'POST',body:data}),payload=response.data||{},cb=onSaved;showToast(response.message||'Medicine saved successfully.',{type:'success',duration:2});closeModal();if(typeof cb==='function')cb(payload.record||payload);}catch(error){Validation.applyErrors(form,error.errors||{});App.showError(error,'Unable to save Medicine.');}finally{save.disabled=false;}});document.getElementById('medicineQuickClose').addEventListener('click',closeModal);document.getElementById('medicineQuickCancel').addEventListener('click',closeModal);modal.addEventListener('click',function(e){if(e.target===modal)closeModal();});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&modal.classList.contains('open'))closeModal();});window.AppMedicineForm={openCreate:openCreate,close:closeModal};})(window,document);</script>